#!/usr/bin/env Rscript
args <- commandArgs(trailingOnly = TRUE); if (!length(args) || !args[[1L]] %in% c("--contract", "--profile", "--integration", "--decision")) stop("Usage: Rscript tools/verify-ou-v1-r3.R --contract|--profile|--integration|--decision", call. = FALSE)
mode <- args[[1L]]; design <- "docs/design/266-ou-v1-r3-likelihood-geometry.md"; runner <- "tools/run-phylo-ou-r3-geometry.R"; root <- file.path("docs", "dev-log", "evidence", "ou-v1-r3"); fail <- function(x) stop(x, call. = FALSE)
if (mode == "--contract") { x <- paste(readLines(design), readLines(runner), collapse = "\n"); if (!all(vapply(c("two prespecified", "Gauss-Hermite", "re-optimise", "--preflight", "--run"), grepl, logical(1L), x = x, fixed = TRUE))) fail("R3 contract incomplete."); cat("OU_V1_R3_CONTRACT_PASS\n") } else { p <- utils::read.csv(file.path(root, "profile.csv")); i <- utils::read.csv(file.path(root, "integration.csv")); if (nrow(p) != 50L || !all(c("delta_objective", "sd_mu", "sd_sigma") %in% names(p)) || sum(is.finite(p$objective)) < 40L) fail("R3 profile incomplete."); if (mode == "--integration" && (nrow(i) != 2L || !all(c("laplace_minus_quadrature", "quadrature_refinement") %in% names(i)) || !is.finite(i$quadrature_refinement[[2L]]))) fail("R3 integration incomplete."); if (mode == "--decision" && (!file.exists(file.path(root, "RESULTS.md")) || !grepl("not a recovery", paste(readLines(file.path(root, "RESULTS.md")), collapse = " "), fixed = TRUE))) fail("R3 claim boundary absent."); cat(switch(mode, `--profile` = "OU_V1_R3_PROFILE_PASS\n", `--integration` = "OU_V1_R3_INTEGRATION_PASS\n", `--decision` = "OU_V1_R3_DECISION_PASS\n")) }
